def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_towards(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def step_away(src, threat):
        sx, sy = src
        tx, ty = threat
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    def safe_xy(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def nearest(points, src):
        best = None
        best_d = None
        sx, sy = src
        for p in points or []:
            if not isinstance(p, (list, tuple)) or len(p) < 2:
                continue
            d = abs(p[0] - sx) + abs(p[1] - sy)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def farthest(points, src):
        best = None
        best_d = None
        sx, sy = src
        for p in points or []:
            if not isinstance(p, (list, tuple)) or len(p) < 2:
                continue
            d = abs(p[0] - sx) + abs(p[1] - sy)
            if best is None or d > best_d:
                best = p
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_xy(observation.get("self_position", (0, 0)))
    ox, oy = safe_xy(observation.get("opponent_position", (sx, sy)))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_towards((sx, sy), (ox, oy))
        w = observation.get("grid_width", 0)
        h = observation.get("grid_height", 0)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = farthest(corners, (ox, oy)) or (0, 0)
        return step_towards((sx, sy), target)

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier_cells")
            or observation.get("targets")
            or []
        )
        target = nearest(targets, (sx, sy))
        if target is not None:
            return step_towards((sx, sy), target)
        return step_away((sx, sy), (ox, oy))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = nearest(resources, (sx, sy))
    if target is not None:
        return step_towards((sx, sy), target)

    carrying = observation.get("carrying", 0)
    home = observation.get("home_position") or observation.get("base_position")
    if carrying and home is not None:
        hx, hy = safe_xy(home, (sx, sy))
        return step_towards((sx, sy), (hx, hy))

    return step_away((sx, sy), (ox, oy))

